<script lang="ts">
	import { Activity, Camera, Home, Play, RefreshCw, Thermometer, X } from '@lucide/svelte';
	import { onMount } from 'svelte';
	import BmsLiveStringPanel from './BmsLiveStringPanel.svelte';
	import { createCalibrationEvent, getBmsDashboardSnapshot, getCalibrationEvent, getDischargeConfig, hasBmsSession, listCalibrationEvents, startCalibrationEvent, type BmsDashboardItem, type CalibrationEventDetail, type CalibrationEventType, type DischargeCurrentDirection } from '$lib/services/bms-api';
	import { BMS_ASSET_PROFILE_EVENT, emptyBmsSiteProfile, loadBmsAssetProfile, type BmsSiteProfile } from '$lib/services/bms-asset-profile';

	let { onOpenCalibration = (_stringIndex:number,_eventId=0) => undefined }: { onOpenCalibration?: (stringIndex:number,eventId?:number) => void } = $props();
	let site=$state<BmsSiteProfile>(emptyBmsSiteProfile());
	let cameraEnabled=$state(false),items=$state<BmsDashboardItem[]>([]),loading=$state(false),error=$state('');
	let activeCalibrations=$state<CalibrationEventDetail[]>([]);
	let calibrateOpen=$state(false),creatingCalibration=$state(false),calibrationCreateError=$state(''),calibrationStringIndex=$state(0);
	let calibrationType=$state<Extract<CalibrationEventType,'INITIAL_BASELINE'|'MONTHLY_INSPECTION'>>('INITIAL_BASELINE');
	let currentDirection=$state<DischargeCurrentDirection>('NEGATIVE');
	let alarmStrings=$derived(items.filter(item=>statusFor(item)==='alarm').length);
	let offlineStrings=$derived(items.filter(item=>statusFor(item)==='offline').length);
	let selectedOpenCalibration=$derived(activeCalibrations.find(event=>stringIndexFor(event)===calibrationStringIndex)??null);

	onMount(()=>{site=loadBmsAssetProfile().site;const updateSite=()=>site=loadBmsAssetProfile().site;window.addEventListener(BMS_ASSET_PROFILE_EVENT,updateSite);void load();const timer=setInterval(()=>void load(false),15000);return()=>{clearInterval(timer);window.removeEventListener(BMS_ASSET_PROFILE_EVENT,updateSite)}});
	async function load(showActivity=true){
		if(!hasBmsSession()){items=[];activeCalibrations=[];error='Connecting to the BMS platform…';return}
		if(showActivity)loading=true;
		try{const data=await getBmsDashboardSnapshot();items=data;const[eventLists,dischargeConfig]=await Promise.all([Promise.all(data.map(item=>listCalibrationEvents(item.config.stringIndex).catch(()=>[]))),getDischargeConfig().catch(()=>null)]);if(dischargeConfig)currentDirection=dischargeConfig.dischargeCurrentDirection;const open=eventLists.flat().filter(event=>['DRAFT','ACTIVE','BLOCKED','REVALIDATION_REQUIRED'].includes(event.status));const unique=[...new Map(open.map(event=>[event.calibrationEventId,event])).values()];activeCalibrations=(await Promise.all(unique.map(event=>getCalibrationEvent(event.calibrationEventId).catch(()=>null)))).filter((event):event is CalibrationEventDetail=>event!==null);error=''}
		catch(cause){error=cause instanceof Error?cause.message:'Unable to load the BMS dashboard.'}
		finally{loading=false}
	}
	function display(value:string){return value.trim()||'Not set'}
	function openCalibrate(){const selected=items.find(item=>{const event=calibrationFor(item);return !event||event.status==='DRAFT'})??items[0];calibrationStringIndex=selected?.config.stringIndex??0;const openEvent=selected?calibrationFor(selected):null;calibrationType=openEvent?.status==='DRAFT'&&openEvent.eventType==='MONTHLY_INSPECTION'?'MONTHLY_INSPECTION':'INITIAL_BASELINE';calibrationCreateError='';calibrateOpen=true}
	function selectCalibrationString(item:BmsDashboardItem){calibrationStringIndex=item.config.stringIndex;const openEvent=calibrationFor(item);if(openEvent?.status==='DRAFT'&&(openEvent.eventType==='INITIAL_BASELINE'||openEvent.eventType==='MONTHLY_INSPECTION'))calibrationType=openEvent.eventType}
	function stringIndexFor(event:CalibrationEventDetail){return Number(event.stringId.replace(/^str/,''))||items[0]?.config.stringIndex||0}
	function calibrationFor(item:BmsDashboardItem){return activeCalibrations.find(event=>stringIndexFor(event)===item.config.stringIndex)??null}
	function duplicateOpenEvent(cause:unknown){const value=cause instanceof Error?cause.message:String(cause);return value.includes('calibration_event_one_open_per_string')||value.toLowerCase().includes('duplicate key')}
	async function recoverOpenCalibration(){const summaries=await listCalibrationEvents(calibrationStringIndex);const summary=summaries.find(event=>['DRAFT','ACTIVE','BLOCKED','REVALIDATION_REQUIRED'].includes(event.status));return summary?getCalibrationEvent(summary.calibrationEventId):null}
	async function createAndStartCalibration(){
		if(!calibrationStringIndex||creatingCalibration||(selectedOpenCalibration?.status!=='DRAFT'&&!!selectedOpenCalibration))return;
		creatingCalibration=true;calibrationCreateError='';
		try{
			let openEvent=selectedOpenCalibration;
			if(!openEvent){
				try{openEvent=calibrationType==='INITIAL_BASELINE'?await createCalibrationEvent({stringIndex:calibrationStringIndex,eventType:'INITIAL_BASELINE',currentDirection,dischargeMethod:'C10',dischargeEndpointMode:'FULL_CUTOFF'}):await createCalibrationEvent({stringIndex:calibrationStringIndex,eventType:'MONTHLY_INSPECTION',currentDirection})}
				catch(cause){if(!duplicateOpenEvent(cause))throw cause;openEvent=await recoverOpenCalibration();if(!openEvent)throw cause}
			}
			const current=openEvent.status==='DRAFT'?await startCalibrationEvent(openEvent.calibrationEventId,openEvent.eventVersion):openEvent;
			activeCalibrations=[current,...activeCalibrations.filter(event=>stringIndexFor(event)!==calibrationStringIndex)];calibrateOpen=false;
		}
		catch(cause){calibrationCreateError=cause instanceof Error?cause.message:'Unable to create and start the calibration event.'}
		finally{creatingCalibration=false}
	}
	function alarms(item:BmsDashboardItem){const summary=item.telemetry.summary,config=item.config,reasons:string[]=[];if(summary.maxResistance!==null&&config.highResistanceThreshold>0&&summary.maxResistance>=config.highResistanceThreshold)reasons.push('R');if(summary.maxTemperature!==null&&config.highTemperatureThreshold>0&&summary.maxTemperature>=config.highTemperatureThreshold)reasons.push('T');if(summary.minVoltage!==null&&config.lowVoltageThreshold>0&&summary.minVoltage<=config.lowVoltageThreshold)reasons.push('V');if(summary.maxVoltage!==null&&config.highVoltageThreshold>0&&summary.maxVoltage>=config.highVoltageThreshold)reasons.push('V');return[...new Set(reasons)]}
	function disconnected(item:BmsDashboardItem){const summary=item.telemetry.summary;return!item.telemetry.active||[summary.avgVoltage,summary.avgResistance,summary.stringVoltage,summary.stringCurrent,summary.avgTemperature].every(value=>value===null)}
	function statusFor(item:BmsDashboardItem){return alarms(item).length?'alarm':disconnected(item)?'offline':'normal'}
</script>

<section class="page">
	<div class="site-card">
		<span class="site-icon"><Home size={20}/></span>
		<div class="site-facts"><div><span>Owner</span><strong>{display(site.owner)}</strong></div><div><span>Operational team</span><strong>{display(site.operationalTeam)}</strong></div><div><span>Substation</span><strong>{display(site.substation)}</strong></div></div>
		<div class="fleet-summary"><span><strong>{items.length}</strong> strings</span><span class:has-alarm={alarmStrings>0}><strong>{alarmStrings}</strong> alarm</span><span class:has-offline={offlineStrings>0}><strong>{offlineStrings}</strong> offline</span></div>
		<button class="calibrate" type="button" disabled={!items.length} onclick={openCalibrate}><Activity size={17}/>Calibrate</button>
		<button class:loading class="refresh" aria-label="Refresh dashboard" disabled={loading} onclick={()=>load()}><RefreshCw size={18}/></button>
	</div>
	{#if error}<div class="request-error">{error}</div>{/if}

	{#if loading&&!items.length}
		<div class="loading-card"><i></i><strong>Loading live string data…</strong></div>
	{:else if items.length}
		<div class="string-grid">{#each items as item (item.config.id)}{@const calibration=calibrationFor(item)}<BmsLiveStringPanel {item} {calibration} onOpenCalibration={()=>onOpenCalibration(item.config.stringIndex,calibration?.calibrationEventId??0)}/>{/each}</div>
	{:else}
		<div class="empty-card"><strong>No battery strings configured</strong><span>Add a string in Battery Strings to begin monitoring.</span></div>
	{/if}

	<details class="thermal-card"><summary><span><Thermometer size={17}/>Thermal camera</span><small>Optional room monitoring</small></summary><div class="thermal-content"><Camera size={19}/><span>{cameraEnabled?'Thermal monitoring is enabled.':'No thermal data available.'}</span><button class:active={cameraEnabled} onclick={()=>cameraEnabled=!cameraEnabled}>{cameraEnabled?'Turn off':'Turn on'}</button></div></details>
	{#if calibrateOpen}<div class="modal-backdrop" role="presentation"><section class="calibrate-dialog" role="dialog" aria-modal="true" aria-labelledby="calibrate-title"><header><div><h2 id="calibrate-title">Create calibration event</h2><p>Select a battery string and event type. The event starts immediately after creation.</p></div><button type="button" aria-label="Close calibration dialog" disabled={creatingCalibration} onclick={()=>calibrateOpen=false}><X size={19}/></button></header><div class="create-calibration-body"><section><h3>Battery string</h3><div class="string-options">{#each items as item}{@const openEvent=calibrationFor(item)}{@const unavailable=!!openEvent&&openEvent.status!=='DRAFT'}<label class:selected={calibrationStringIndex===item.config.stringIndex} class:unavailable><input type="radio" name="calibration-string" value={item.config.stringIndex} checked={calibrationStringIndex===item.config.stringIndex} disabled={unavailable} onchange={()=>selectCalibrationString(item)}/><span><strong>{item.config.stringName}</strong><small>{item.config.cellQty} cells · {item.config.cellBrand} {item.config.cellModel}{openEvent?.status==='DRAFT'?` · Draft #${openEvent.calibrationEventId} will be started`:unavailable?` · Calibration ${openEvent?.status.toLowerCase().replaceAll('_',' ')}`:''}</small></span></label>{/each}</div></section><section><h3>Event type</h3><div class="event-options"><label class:selected={calibrationType==='INITIAL_BASELINE'} class:locked={selectedOpenCalibration?.status==='DRAFT'}><input type="radio" name="calibration-type" value="INITIAL_BASELINE" disabled={selectedOpenCalibration?.status==='DRAFT'} bind:group={calibrationType}/><span><strong>Initial Baseline</strong><small>First charge, discharge and baseline measurement workflow</small></span></label><label class:selected={calibrationType==='MONTHLY_INSPECTION'} class:locked={selectedOpenCalibration?.status==='DRAFT'}><input type="radio" name="calibration-type" value="MONTHLY_INSPECTION" disabled={selectedOpenCalibration?.status==='DRAFT'} bind:group={calibrationType}/><span><strong>Monthly Inspection</strong><small>Periodic operational inspection and recorded measurements</small></span></label></div>{#if selectedOpenCalibration?.status==='DRAFT'}<p class="draft-note">Event #{selectedOpenCalibration.calibrationEventId} already exists for this string. It will be started instead of creating a duplicate.</p>{/if}</section>{#if calibrationCreateError}<div class="create-error">{calibrationCreateError}</div>{/if}</div><footer><button class="secondary" type="button" disabled={creatingCalibration} onclick={()=>calibrateOpen=false}>Cancel</button><button class="primary" type="button" disabled={!calibrationStringIndex||creatingCalibration||(selectedOpenCalibration?.status!=='DRAFT'&&!!selectedOpenCalibration)} onclick={createAndStartCalibration}><Play size={16}/>{creatingCalibration?'Starting…':selectedOpenCalibration?.status==='DRAFT'?'Start existing event':'Create & start'}</button></footer></section></div>{/if}
</section>

<style>
	.page{animation:enter .18s ease-out}.site-card{display:flex;align-items:center;gap:14px;min-height:76px;padding:13px 15px;border:1px solid #e1e7f0;border-radius:11px;background:#fff}.site-icon{display:grid;flex:0 0 38px;width:38px;height:38px;place-items:center;border-radius:9px;color:#2653ba;background:#eaf0ff}.site-facts{display:grid;grid-template-columns:repeat(3,minmax(120px,1fr));min-width:0;max-width:760px;flex:1}.site-facts>div{min-width:0;padding:0 15px;border-right:1px solid #e7ecf3}.site-facts>div:first-child{padding-left:0}.site-facts>div:last-child{border-right:0}.site-facts span,.site-facts strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.site-facts span{color:#78859a;font-size:11px}.site-facts strong{margin-top:5px;color:#2f425e;font-size:14px;font-weight:600}.fleet-summary{display:flex;gap:7px;margin-left:auto}.fleet-summary span{display:inline-flex;align-items:baseline;gap:4px;padding:6px 9px;border-radius:13px;color:#647187;background:#f3f5f8;font-size:11px}.fleet-summary strong{color:#35465f;font-size:13px;font-weight:500}.fleet-summary .has-alarm{color:#a74138;background:#fff0ef}.fleet-summary .has-alarm strong{color:#b7352c}.fleet-summary .has-offline{color:#6e7785;background:#edf0f4}.calibrate{display:inline-flex;align-items:center;gap:7px;height:38px;padding:0 12px;border:0;border-radius:8px;color:#fff;background:#1749ad;font:inherit;font-size:13px;font-weight:600;cursor:pointer}.calibrate:disabled{opacity:.5;cursor:not-allowed}.refresh{display:grid;width:36px;height:36px;place-items:center;border:1px solid #d9e1ec;border-radius:8px;color:#496389;background:#fff;cursor:pointer}.refresh.loading :global(svg){animation:spin .8s linear infinite}.request-error{margin-top:10px;padding:9px 11px;border:1px solid #efddae;border-radius:8px;color:#765b28;background:#fff9e9;font-size:12px}
	.string-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;align-items:start;margin-top:14px}.loading-card,.empty-card{display:grid;min-height:330px;margin-top:14px;place-content:center;justify-items:center;border:1px solid #e1e7f0;border-radius:12px;color:#79869a;background:#fff;text-align:center}.loading-card i{width:25px;height:25px;margin-bottom:10px;border:2px solid #dce5f2;border-top-color:#2c5ab4;border-radius:50%;animation:spin .8s linear infinite}.loading-card strong,.empty-card strong{color:#40516c;font-size:14px;font-weight:500}.empty-card span{margin-top:6px;font-size:12px}.thermal-card{margin-top:14px;border:1px solid #e1e7f0;border-radius:10px;background:#fff}.thermal-card summary{display:flex;align-items:center;justify-content:space-between;padding:11px 13px;color:#4b5d76;cursor:pointer;list-style:none}.thermal-card summary::-webkit-details-marker{display:none}.thermal-card summary span{display:flex;align-items:center;gap:7px;font-size:13px}.thermal-card summary small{color:#8a95a6}.thermal-content{display:flex;align-items:center;gap:8px;padding:12px 13px;border-top:1px solid #edf1f5;color:#7b8799;font-size:12px}.thermal-content button{margin-left:auto;padding:5px 9px;border:0;border-radius:6px;color:#4d6385;background:#edf2f9;cursor:pointer}.thermal-content button.active{color:#28734b;background:#ebf7ef}@keyframes spin{to{transform:rotate(360deg)}}@keyframes enter{from{opacity:0;transform:translateY(4px)}}
	.site-card{min-height:84px;padding:15px 17px}.site-icon{width:42px;height:42px}.fleet-summary{gap:8px}.fleet-summary span{padding:7px 11px;font-size:13px}.fleet-summary strong{font-size:15px;font-weight:600}.refresh{width:40px;height:40px}.request-error{font-size:14px}.loading-card strong,.empty-card strong{font-size:16px}.empty-card span{font-size:14px}.thermal-card summary{padding:14px 15px}.thermal-card summary span{gap:8px;font-size:16px;font-weight:500}.thermal-card summary small{color:#63738a;font-size:13px}.thermal-content{padding:14px 15px;color:#596b82;font-size:14px}.thermal-content button{padding:7px 11px;font-size:14px}.modal-backdrop{position:fixed;inset:0;z-index:400;display:grid;place-items:center;padding:18px;background:rgba(20,35,60,.32)}.calibrate-dialog{width:min(560px,100%);max-height:calc(100vh - 36px);overflow:auto;border:1px solid #dfe6ef;border-radius:13px;background:#fff;box-shadow:0 24px 70px rgba(22,40,72,.24)}.calibrate-dialog>header{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;padding:18px 20px;border-bottom:1px solid #e8edf4}.calibrate-dialog h2{margin:0;color:#263a57;font-size:19px}.calibrate-dialog header p{margin:5px 0 0;color:#718096;font-size:13px}.calibrate-dialog header button{display:grid;width:30px;height:30px;place-items:center;border:0;border-radius:7px;color:#617087;background:#f3f6fa;cursor:pointer}.create-calibration-body{display:grid;gap:18px;padding:17px 20px}.create-calibration-body h3{margin:0 0 9px;color:#40516c;font-size:13px;font-weight:600}.string-options,.event-options{display:grid;gap:8px}.string-options label,.event-options label{display:flex;align-items:center;gap:11px;padding:11px 12px;border:1px solid #e0e7f0;border-radius:9px;cursor:pointer}.string-options label.selected,.event-options label.selected{border-color:#91afe1;background:#f4f8ff}.string-options label.unavailable,.event-options label.locked{cursor:not-allowed;opacity:.58;background:#f5f6f8}.string-options input,.event-options input{width:16px;height:16px;flex:none;accent-color:#1749ad}.string-options label span,.event-options label span{display:grid;gap:4px}.string-options strong,.event-options strong{color:#30445f;font-size:14px}.string-options small,.event-options small{color:#748299;font-size:12px}.draft-note{margin:9px 0 0;padding:8px 10px;border-radius:7px;color:#755a26;background:#fff7e8;font-size:12px;line-height:1.4}.create-error{padding:9px 11px;border-radius:7px;color:#a53b31;background:#fff1ef;font-size:12px}.calibrate-dialog footer{display:flex;justify-content:flex-end;gap:8px;padding:12px 20px;border-top:1px solid #e8edf4}.calibrate-dialog footer button{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:38px;padding:0 13px;border-radius:8px;font:inherit;font-size:13px;font-weight:600;cursor:pointer}.calibrate-dialog footer .secondary{border:1px solid #d8e0eb;color:#40516f;background:#fff}.calibrate-dialog footer .primary{border:0;color:#fff;background:#1749ad}.calibrate-dialog footer button:disabled,.calibrate-dialog header button:disabled{opacity:.5;cursor:not-allowed}
	@media(max-width:1180px){.string-grid{grid-template-columns:1fr}.site-facts{max-width:none}}@media(max-width:900px){.site-card{align-items:flex-start;flex-wrap:wrap}.site-facts{order:2;flex-basis:calc(100% - 60px)}.fleet-summary{order:3;width:100%;margin-left:0}.calibrate{margin-left:auto}}@media(max-width:620px){.site-facts{grid-template-columns:1fr;gap:9px}.site-facts>div{padding:0;border:0}}@media(max-width:520px){.fleet-summary{flex-wrap:wrap}.calibrate{order:4;width:100%;justify-content:center}}
</style>
